import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, rev, capacity, cost;
        public Edge(int to, int rev, int capacity, int cost) {
            this.to = to;
            this.rev = rev;
            this.capacity = capacity;
            this.cost = cost;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        final int Z = 100;
        final int N = Z * Z;
        int s = 0;
        int t = n * 100 + 1;

        List<Edge>[] graph = new ArrayList[N + 2];
        for (int i = 0; i <= N + 1; i++) {
            graph[i] = new ArrayList<>();
        }

        // Helper function to add edges
        BiConsumer<Integer, Edge> addEdge = (u, e) -> {
            graph[u].add(e);
        };

        // Function to add edges in the flow network
        BiConsumer<Integer, Integer> addEdgeBetweenNodes = (u, v) -> {
            addEdge.accept(u, new Edge(v, graph[v].size(), 1, c + (k * k - (k - 1) * (k - 1)) * d));
            addEdge.accept(v, new Edge(u, graph[u].size() - 1, 0, - (c + (k * k - (k - 1) * (k - 1)) * d)));
        };

        // Read input
        StringTokenizer st2 = new StringTokenizer(br.readLine());
        int[] vArr = new int[k];
        for (int i = 0; i < k; i++) {
            vArr[i] = Integer.parseInt(st2.nextToken());
        }

        // Build graph
        for (int i = 1; i <= 100; i++) {
            addEdge.accept(i, new Edge(t, graph[t].size(), 100, 0));
            graph[t].add(new Edge(i, graph[i].size() - 1, 0, 0));
        }

        for (int v : vArr) {
            int uNode = (v - 1) * 100 + 1;
            addEdge.accept(s, new Edge(uNode, graph[uNode].size(), 1, 0));
            graph[s].add(new Edge(uNode, graph[uNode].size() - 1, 0, 0));
        }

        // For each node, add edges for movement within the same node
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j < 100; j++) {
                int uNode = (i - 1) * 100 + j;
                int vNode = (i - 1) * 100 + j + 1;
                addEdge.accept(uNode, new Edge(vNode, graph[vNode].size(), 100, c));
                graph[vNode].add(new Edge(uNode, graph[uNode].size() - 1, 0, -c));
            }
        }

        // Read edges between nodes
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());

            for (int j = 1; j < 100; j++) {
                int idx = (u - 1) * 100 + j;
                int idy = (v - 1) * 100 + j + 1;
                for (int k = 1; k <= 50; k++) {
                    int costVal = c + (k * k - (k - 1) * (k - 1)) * d;
                    addEdge.accept(idx, new Edge(idy, graph[idy].size(), 1, costVal));
                    graph[idy].add(new Edge(idx, graph[idx].size() - 1, 0, -costVal));
                }
            }
            for (int j = 1; j < 100; j++) {
                int idx = (v - 1) * 100 + j;
                int idy = (u - 1) * 100 + j + 1;
                for (int k = 1; k <= 50; k++) {
                    int costVal = c + (k * k - (k - 1) * (k - 1)) * d;
                    addEdge.accept(idx, new Edge(idy, graph[idy].size(), 1, costVal));
                    graph[idy].add(new Edge(idx, graph[idx].size() - 1, 0, -costVal));
                }
            }
        }

        int totalFlow = 0;
        int totalCost = 0;
        int[] dist = new int[N + 2];
        int[] parent = new int[N + 2];
        int[] parentEdge = new int[N + 2];

        while (true) {
            Arrays.fill(dist, Integer.MAX_VALUE);
            dist[s] = 0;
            boolean[] inQueue = new boolean[N + 2];
            Queue<Integer> queue = new LinkedList<>();
            queue.offer(s);
            inQueue[s] = true;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                inQueue[u] = false;
                for (int i = 0; i < graph[u].size(); i++) {
                    Edge e = graph[u].get(i);
                    if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost) {
                        dist[e.to] = dist[u] + e.cost;
                        parent[e.to] = u;
                        parentEdge[e.to] = i;
                        if (!inQueue[e.to]) {
                            queue.offer(e.to);
                            inQueue[e.to] = true;
                        }
                    }
                }
            }

            if (dist[t] == Integer.MAX_VALUE) break;

            int flow = Integer.MAX_VALUE;
            for (int u = t; u != s; u = parent[u]) {
                flow = Math.min(flow, graph[parent[u]].get(parentEdge[u]).capacity);
            }

            for (int u = t; u != s; u = parent[u]) {
                Edge e = graph[parent[u]].get(parentEdge[u]);
                e.capacity -= flow;
                graph[u].get(e.rev).capacity += flow;
            }

            totalCost += dist[t] * flow;
            totalFlow += flow;
        }

        System.out.println(totalCost);
    }
}
